def matrices(text):
    pattern=r'\\begin\{(array|bmatrix)\}(?:\{[^}]*\})?(.*?)\\end\{\1\}'
    return [[[int(n.strip()) for n in row.split('&')] for row in body.split('\\\\') if row.strip()] for _,body in re.findall(pattern,text,re.S)]
def systems(text):
    blocks=[]
